#!/usr/bin/env python3

# This script requires `sbcast_times.csv`, generated by `create_sbcast_times_csv.sh`
# This script generates one file: setup_times.png
# which are figures that have 1 unique set of axes per benchmark

import matplotlib.pyplot as plt
import matplotlib.axes as mplax
from matplotlib.patches import Patch
import numpy as np
import os
import pandas as pd
import re

if not os.path.isfile('sbcast_times.csv'):
    print("Missing required input file setup_times.csv. Please run create_setup_times_csv.sh first.")
    exit(1)

df = pd.read_csv('sbcast_times.csv')

# Now, summarize cold/warm timings with avg & stdev
df_grouped = df.groupby(['benchmark', 'tool', 'nnodes'])['seconds'].agg(['mean', 'std', 'min', 'max'])
print(df_grouped)
df_grouped = df_grouped.reset_index()

fig, ax = plt.subplots(1, 1, figsize=(5, 5))

# Custom legend
legend_colors = ["#000000", "#E69F00", "#56B4E9", "#009E73"]
legend_labels = ['osu', 'pynamic', 'python-mpi4py', 'python-pytorch']

legend_labels_to_index = {}
for i in range(0, len(legend_labels)):
    legend_labels_to_index[legend_labels[i]] = i

legend_handles = [Patch(color=color, label=label) for color, label in zip(legend_colors, legend_labels)]
legend_labels = [h.get_label() for h in legend_handles]
fig.legend(legend_handles, legend_labels, loc='upper center', bbox_to_anchor=(0.5, 0.15), ncol=2, frameon=False, fontsize=12)
fig.tight_layout(rect=[0.05, 0.18, 1, 0.95])

# Set labels, scales
ax.set_ylabel("Time (s)", fontsize=14)
ax.set_xlabel("# Nodes", fontsize=14)
ax.tick_params(axis='both', labelsize=12)
ax.set_xscale('log')
ax.set_ylim(0.0, 150)
ax.set_xlim(0.5, 3000)
ax.set_title(f"Measured sbcast overhead", fontsize=16)

# For each unique benchmark/tool, get & plot data
for index, entry in df_grouped[['benchmark', 'tool']].drop_duplicates().iterrows():
    single_series_df = df_grouped[df_grouped['benchmark'] == entry['benchmark']]
    nnodes = single_series_df['nnodes'].to_numpy()
    time_avg = single_series_df['mean'].to_numpy()
    #time_stdev = single_series_df['std'].to_numpy()
    time_min = single_series_df['min'].to_numpy()
    time_max = single_series_df['max'].to_numpy()
    sorted_indices = nnodes.argsort()
    nnodes_sorted = nnodes[sorted_indices]
    time_avg_sorted = time_avg[sorted_indices]
    time_min_sorted = time_min[sorted_indices]
    time_max_sorted = time_max[sorted_indices]
    #err_bars = time_stdev[sorted_indices]
    # slice min/max time into a single array
    err_bars = [time_avg_sorted - time_min_sorted, time_max_sorted - time_avg_sorted]
    ax.errorbar(nnodes_sorted, time_avg_sorted, yerr=err_bars, fmt='-o', capsize=8, capthick=3, elinewidth=0.5, color=legend_colors[legend_labels_to_index[entry['benchmark']]])

plt.savefig(f'sbcast_setup_times.png', dpi=200)

